const payload = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
msg.originalPayload = payload;
msg.medicalRequest = {
  sintomas: Array.isArray(payload.sintomas) ? payload.sintomas : [],
  tipoEnfermedad: payload.tipoEnfermedad || "general",
  grupoEdad: payload.grupoEdad || "adulto",
  sexo: payload.sexo || "otro",
  nivelUrgencia: payload.nivelUrgencia || "media",
  contextoClinico: payload.contextoClinico || "consulta general"
};
msg.simulatedMedicalObjects = Array.isArray(payload.objetosSimulados)
  ? payload.objetosSimulados.map((item) => String(item).toLowerCase())
  : [];
if (payload.imageBase64) {
  const base64 = String(payload.imageBase64).replace(/^data:image\/\w+;base64,/, "");
  msg.payload = Buffer.from(base64, "base64");
  msg.hasImage = msg.payload.length > 0;
} else {
  msg.payload = Buffer.alloc(0);
  msg.hasImage = false;
}
return msg;

const detections = Array.isArray(msg.payload)
  ? msg.payload
  : Array.isArray(msg.payload?.detections)
    ? msg.payload.detections
    : [];
const detected = new Set(msg.simulatedMedicalObjects || []);
for (const item of detections) {
  const label = String(item.class || item.label || item.detectedClass || "").toLowerCase();
  if (!label) {
    continue;
  }
  // COCO-SSD no trae etiquetas medicas exactas; por eso se aplica una capa de correlacion.
  if (label.includes("bottle") || label.includes("cup")) {
    detected.add("pastillas");
  }
  if (label.includes("remote") || label.includes("cell phone")) {
    detected.add("glucometro");
  }
  if (label.includes("toothbrush") || label.includes("knife")) {
    detected.add("jeringa");
  }
}
msg.objetosTensorflow = detections;
msg.objetosDetectados = Array.from(detected);
return msg;

const detected = new Set(msg.simulatedMedicalObjects || []);
const symptoms = Array.isArray(msg.medicalRequest?.sintomas)
  ? msg.medicalRequest.sintomas.join(" ").toLowerCase()
  : "";
if (msg.medicalRequest?.tipoEnfermedad === "metabolica" || symptoms.includes("sed excesiva") || symptoms.includes("vision borrosa")) {
  detected.add("glucometro");
}
if (msg.medicalRequest?.tipoEnfermedad === "infecciosa" || symptoms.includes("fiebre")) {
  detected.add("pastillas");
}
msg.objetosTensorflow = [];
msg.objetosDetectados = Array.from(detected);
return msg;

msg.headers = { "Content-Type": "application/json" };
msg.payload = {
  ...msg.medicalRequest,
  objetosDetectados: msg.objetosDetectados || [],
  fuenteVision: {
    modo: msg.hasImage ? "tensorflow+capa_simulada" : "simulacion",
    deteccionesBrutas: Array.isArray(msg.objetosTensorflow) ? msg.objetosTensorflow.length : 0
  }
};
return msg;

msg.payload = {
  ok: true,
  correlacion: {
    objetosDetectados: msg.objetosDetectados || [],
    origenVision: msg.hasImage ? "TensorFlow COCO-SSD + correlacion" : "Simulacion clinica",
    nota: "COCO-SSD se complementa con una capa de reglas para representar jeringa, glucometro y pastillas."
  },
  diagnostico: msg.payload
};
return msg;

msg.statusCode = 500;
msg.payload = {
  ok: false,
  error: {
    code: "NODE_RED_FLOW_ERROR",
    message: msg.error?.message || "Ocurrio un error en el flujo medico de Node-RED."
  }
};
return msg;
